MATCH (c:Company)
WHERE (
  EXISTS {
    MATCH (c)-[:operatesIn]->(:Industry {name: 'television'})
  }
  OR
  EXISTS {
    MATCH (c)-[:basedIn]->(:Country {name: 'Australia'})
  }
)
RETURN c.name AS company_name

CALL {
  MATCH (c:Company)-[:basedIn]->(country:Country)
  WHERE country.name = 'United States of America'
  RETURN c AS company
  UNION
  MATCH (c:Company)-[:subsidiaryOf]->(parent:Company)
  WHERE parent.name = 'Mentor Graphics (Hungary)'
  RETURN c AS company
}
RETURN COUNT(DISTINCT company) AS numberOfCompanies;
